function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 3) return 'mat needs 1 to 3 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 3) return 'Each row needs 1 to 3 cells.';
  if (mat.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (mat.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  return null;
}

