function minFlips(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const cells = rows * cols;

  let start = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (mat[r][c] === 1) start |= 1 << (r * cols + c);
    }
  }

  const moves = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let mask = 1 << (r * cols + c);
      if (r > 0) mask |= 1 << ((r - 1) * cols + c);
      if (r < rows - 1) mask |= 1 << ((r + 1) * cols + c);
      if (c > 0) mask |= 1 << (r * cols + c - 1);
      if (c < cols - 1) mask |= 1 << (r * cols + c + 1);
      moves.push(mask);
    }
  }

  const steps = new Array(1 << cells).fill(-1);
  steps[start] = 0;
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const state = queue[head];
    if (state === 0) return steps[state];
    for (const mask of moves) {
      const next = state ^ mask;
      if (steps[next] === -1) {
        steps[next] = steps[state] + 1;
        queue.push(next);
      }
    }
  }
  return -1;
}

