function minFlips(mat) {
  // Flipping a cell twice undoes it and order does not matter, so try every set of cells to flip once.
  const m = mat.length, n = mat[0].length, total = m * n;
  let best = -1;
  for (let subset = 0; subset < (1 << total); subset++) {
    const grid = mat.map(row => row.slice());
    let count = 0;
    for (let i = 0; i < total; i++) {
      if (!((subset >> i) & 1)) continue;
      count++;
      const r = Math.floor(i / n), c = i % n;
      for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const x = r + dr, y = c + dc;
        if (x >= 0 && x < m && y >= 0 && y < n) grid[x][y] ^= 1;
      }
    }
    if (grid.every(row => row.every(v => v === 0)) && (best === -1 || count < best)) best = count;
  }
  return best;
}

