function generate(rand, size) {
  const m = size === 'large' ? 3 : 1 + Math.floor(rand() * 3);
  const n = size === 'large' ? 3 : 1 + Math.floor(rand() * 3);
  // Vary the density so all-zero, sparse and dense grids all appear.
  const density = [0, 0.2, 0.5, 0.8, 1][Math.floor(rand() * 5)];
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
}
